export const SECURITY_DEPOSIT_GUARANTEE_BY_UNIT: Record<string, SecurityDepositGuaranteeEntry> = Object.fromEntries(
  SECURITY_DEPOSIT_GUARANTEE_ENTRIES.map((e) => [e.unitCode.toUpperCase(), e])
);

export const SECURITY_DEPOSIT_GUARANTEE_BY_RECEIPT: Record<string, SecurityDepositGuaranteeEntry> = Object.fromEntries(
  SECURITY_DEPOSIT_GUARANTEE_ENTRIES.map((e) => [e.receiptNo.toUpperCase(), e])
);

export function resolvePropertyFromUnitCode(unitCode?: string | null): string {
  if (!unitCode) return "Main Portfolio";
  const prefix = String(unitCode).trim().toUpperCase().split("-")[0];
  const map: Record<string, string> = {
    OA20: "Al Ameen Residence 20",
    OA22: "Al Ameen Residence 22",
    OA24: "Al Ameen Residence 24",
    OA26: "Al Ameen Residence 26",
    MN30: "Al Ameen Residence 30",
    MN31: "Al Ameen Residence 31",
    OS40: "Al Ameen Residence 40",
    OS41: "Al Ameen Residence 41",
    BO60: "Al Ameen Residence 60",
    BO61: "Al Ameen Residence 61",
    SD70: "Al Ameen Residence 70",
    MS80: "Al Ameen Residence 80",
    MG90: "Al Ameen Residence 90",
    WK95: "Wakra - 01",
    MV: "Muaither Villa",
    MSV: "Umm Salal Villa",
  };
  return map[prefix] || prefix;
}
